
  import '@webcomponents/scoped-custom-element-registry';
  import '@omicronenergy/oscd-shell/oscd-shell.js';
  import { plugins } from './plugins.js';
  import { compasApi } from './compasApi.js';

  const injectCompasApi = plugin => {
    if (plugin) plugin.compasApi ??= compasApi;
  };

  customElements.whenDefined('oscd-shell').then(async () => {
    const editor = document.querySelector('oscd-shell');
    await editor.updateComplete;
    editor.plugins = plugins;

    customElements.whenDefined('oscd-bay-template-editor').then(() => {
      injectCompasApi(
        editor.shadowRoot?.querySelector('oscd-bay-template-editor')
      );
    });

    const params = new URL(document.location).searchParams;
    for (const [name, value] of params) {
      editor.setAttribute(name, value);
    }
  });
